"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10156"],{13809(e){e.exports=JSON.parse('{"id":"FIN-1015","slug":"tax-shelter","term":"Tax Shelter","also_known_as":[],"difficulty":"Intermediate","definition":"A tax shelter is an investment, account or arrangement that legally reduces or defers the tax a person or business must pay.","explanation":["Many tax shelters are encouraged by governments. Retirement accounts, tax-free savings accounts and certain government bonds are common examples. They offer tax advantages to promote saving, investment or particular activities.","For example, contributions to a retirement account may reduce taxable income now, and the investments inside may grow without being taxed each year. This shelters the money from tax until withdrawal, or in some accounts permanently.","The term also has a negative meaning. Abusive tax shelters are complex schemes designed mainly to avoid tax rather than for any genuine economic purpose, such as artificial losses or circular transactions. Tax authorities challenge these schemes, and participants can face back taxes, interest and penalties.","The line between legitimate planning and abusive avoidance can be blurry. A useful test is whether the arrangement uses a tax benefit in the way lawmakers intended. Promoters offering unusually large tax savings with little real investment risk are a common warning sign."],"note":"","total":1725,"prev":{"slug":"tax-revenue","term":"Tax Revenue"},"next":{"slug":"tax-treaty","term":"Tax Treaty"}}')}}]);